WITH eu AS (SELECT e.id AS executivo_id, COALESCE(e.cargo = 'Agente de prospecção', false) AS agente, lower(u.email) = (SELECT valor FROM configuracao WHERE chave = 'admin_email') AS admin FROM INT_USER u LEFT JOIN executivos e ON lower(e.email) = lower(u.email) AND e.ativo WHERE u.user_id = CAST(:VAR_USER AS UUID) AND u.enabled AND lower(u.email) LIKE '%@' || (SELECT valor FROM configuracao WHERE chave = 'dominio')), notas AS (SELECT a.lab_id, avg(a.nota) AS media, count(a.id) AS avaliacoes FROM banner_lab_avaliacoes a GROUP BY a.lab_id) SELECT l.id, l.rodada_id, r.numero AS rodada, l.pedido_id, p.cliente, p.site, p.portal_url, l.modelo, l.situacao, l.erro, l.aplicado_em, l.gerado_em, n.media, COALESCE(n.avaliacoes, 0) AS avaliacoes, minha.nota AS minha_nota, minha.marcas AS minhas_marcas, minha.comentario AS meu_comentario, (SELECT string_agg(f.conteudo_base64, '' ORDER BY f.parte) FROM pedido_arquivos f WHERE f.pedido_id = l.pedido_id AND f.tipo = 'lab:' || l.id || ':login') AS login_base64, (SELECT string_agg(f.conteudo_base64, '' ORDER BY f.parte) FROM pedido_arquivos f WHERE f.pedido_id = l.pedido_id AND f.tipo = 'lab:' || l.id || ':cabecalho') AS cabecalho_base64 FROM banner_lab l JOIN eu ON (eu.admin OR eu.agente) JOIN banner_lab_rodadas r ON r.id = l.rodada_id JOIN pedidos p ON p.pedido_id = l.pedido_id LEFT JOIN notas n ON n.lab_id = l.id LEFT JOIN banner_lab_avaliacoes minha ON minha.lab_id = l.id AND minha.executivo_id = eu.executivo_id WHERE (:rodada IS NULL OR :rodada = '' OR r.numero = CAST(:rodada AS INTEGER)) AND (:filtro IS NULL OR :filtro = '' OR (:filtro = 'pendentes' AND minha.id IS NULL AND l.situacao = 'pronto') OR (:filtro = 'avaliados' AND minha.id IS NOT NULL)) ORDER BY r.numero DESC, l.id LIMIT CAST(:limite AS INTEGER) OFFSET CAST(:offset AS INTEGER)
